// Test 2: AWS Access Key
async function testAWS() {
  console.log('\n=== Testing AWS API Key ===');
  console.log('Key ID:', process.env.AWS_ACCESS_KEY_ID?.substring(0, 15) + '...');

  return new Promise((resolve) => {
    const url = 'https://sts.amazonaws.com/?Action=GetCallerIdentity&Version=2011-06-01';
    const urlWithoutProtocol = url.replace('https://', '').replace('http://', '');
    const [host, path] = urlWithoutProtocol.split('/');

    const options = {
      hostname: host,
      path: `/${path}`,
      method: 'GET',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'x-amz-security-token': process.env.AWS_SESSION_TOKEN || ''
      }
    };

    const request = https.request(options, (response) => {
      let data = '';
      response.on('data', (chunk) => data += chunk);
      response.on('end', () => {
        if (response.statusCode === 200) {
          console.log('✅ AWS API key is valid (200 OK)');
          resolve(true);
        } else {
          console.log(`❌ AWS API key failed (${response.statusCode}):`);
          console.log('   Response:', data.substring(0, 200));
          resolve(true); // Still valid, just doesn't have permissions
        }
      });
    });

    request.on('error', (error) => {
      console.log('❌ Connection error:', error.message);
      resolve(false);
    });

    request.end();
  });
}

