// Secure application with proper error handling and input validation
const express = require('express');
const helmet = require('helmet');
const csrf = require('csurf');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const morgan = require('morgan');
const compression = require('compression');
const bodyParser = require('body-parser');
const requestLogger = require('./middleware/requestLogger');

const app = express();

/**
 * Security Middleware Configuration
 */
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
      fontSrc: ["'self'", 'data:'],
      objectSrc: ["'none'"],
      mediaSrc: ["'none'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Trust proxy for rate limiting behind load balancer
app.set('trust proxy', 1);

// Security headers middleware manually
app.use((req, res, next) => {
  res.removeHeader('X-Powered-By');
  next();
});

// XSS protection middleware
app.use(xss());

// Rate limiting - Prevent abuse and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    retryAfter: 3600000, // 1 hour
    code: 'RATE_LIMIT_EXCEEDED',
  },
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.path === '/health', // Skip rate limiting for health check
});

app.use(limiter);

// Compression for response size optimization
app.use(compression());

// Request logging middleware
app.use(requestLogger);

// Rate limiting for specific routes (more strict)
const stricterLimiter = rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 10, // limit each IP to 10 requests per minute
  message: {
    error: 'Too many requests, control panel access is limited.',
    code: 'RESTRICTED_RATE_LIMIT',
  },
});

/**
 * Internationalization and locale validation
 */
function validateLocale(locale) {
  const allowedLocales = ['en-US', 'en-GB', 'fr-FR', 'de-DE', 'es-ES'];
  return allowedLocales.includes(locale) ? locale : 'en-US';
}

/**
 * Health check endpoint with rate limiting disabled
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    version: '1.0.0',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV || 'development',
  });
});

/**
 * Users endpoint with input validation
 */
app.get('/users', stricterLimiter, (req, res, next) => {
  try {
    // Validate query parameters
    const { locale, page = '1', limit = '50' } = req.query;

    // Validate locale
    const validLocale = validateLocale(locale);

    // Validate pagination parameters
    const pageNum = parseInt(page, 10);
    const limitNum = parseInt(limit, 10);

    if (isNaN(pageNum) || pageNum < 1) {
      return res.status(400).json({
        error: 'Invalid page number',
        code: 'INVALID_PAGE_NUMBER',
        message: 'Page number must be a positive integer',
      });
    }

    if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        error: 'Invalid limit value',
        code: 'INVALID_LIMIT_VALUE',
        message: 'Limit must be between 1 and 100',
      });
    }

    // Return mock data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', locale: validLocale },
      { id: 2, name: 'Bob', email: 'bob@example.com', locale: validLocale },
    ];

    res.json({
      data: users,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: users.length,
      },
      meta: {
        timestamp: new Date().toISOString(),
      },
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Error handling middleware - Must be last
 */
app.use((error, req, res, next) => {
  // Log the error for monitoring
  console.error('Error occurred:', {
    message: error.message,
    stack: error.stack,
    path: req.path,
    method: req.method,
  });

  // Handle specific error types
  if (error.code) {
    return res.status(error.code).json({
      error: error.message || 'An error occurred',
      code: error.code,
      timestamp: new Date().toISOString(),
    });
  }

  // Default to 500 for unexpected errors
  res.status(500).json({
    error: 'Internal server error',
    code: 'INTERNAL_SERVER_ERROR',
    timestamp: new Date().toISOString(),
  });
});

// Handle uncaught exceptions and promises
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, closing server...');
  const server = app.listen(3000, () => {
    server.close(() => {
      console.log('Server closed gracefully');
      process.exit(0);
    });
  });
  setTimeout(() => {
    console.error('Forcing server close after timeout');
    process.exit(1);
  }, 10000);
});

module.exports = app;

/**
 * Request logging middleware for security monitoring and debugging
 */
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

// Determine log file path based on environment
const logDir = path.join(__dirname, 'logs');
const logFile = path.join(logDir, 'access.log');

// Create logs directory if it doesn't exist
if (!fs.existsSync(logDir)) {
  fs.mkdirSync(logDir, { recursive: true });
}

// Create log stream
const accessLogStream = fs.createWriteStream(logFile, { flags: 'a' });

// Custom log format for security events
const securityLogFormat = ':remote-addr - - [:date[iso]] ":method :url HTTP/:http-version" :status :res[content-length] ":referrer" ":user-agent"';

// Log server events for monitoring security events
morgan.token('ip', (req) => {
  const forwarded = req.headers['x-forwarded-for'];
  return forwarded ? forwarded.split(',')[0] : req.connection.remoteAddress;
});

// Middleware to log security-relevant information
const securityLogMiddleware = (req, res, next) => {
  const startTime = Date.now();

  // Log security-relevant headers
  if (req.headers['x-csrf-token'] || req.headers['csrf-token']) {
    console.warn(`CSRF detection for ${req.method} ${req.path} from ${req.ip}`);
  }

  // Log rate limiting events
  if (req.rateLimit && req.rateLimit.remaining <= 0) {
    console.warn(`Rate limit exceeded for ${req.ip} on ${req.method} ${req.path}`);
  }

  // Log audit events in production
  if (process.env.NODE_ENV === 'production') {
    console.log(`[${new Date().toISOString()}] ${req.ip} - ${req.method} ${req.path} - ${res.statusCode} - ${req.headers['user-agent']}`);
  }

  // Capture response status
  const originalSend = res.send;
  res.send = function (data) {
    const duration = Date.now() - startTime;
    console.log(`Response completed: ${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);

    // Log security-sensitive status codes
    if ([401, 403, 500].includes(res.statusCode)) {
      console.error(`Security alert: ${req.method} ${req.path} returned ${res.statusCode} from ${req.ip}`);
    }

    originalSend.call(this, data);
  };

  next();
};

// Add security logging using Morgan
app.use(morgan('combined', { stream: accessLogStream }));
app.use(securityLogMiddleware);

module.exports = securityLogMiddleware;

/**
 * Security testing for app.js
 * Run with: node test-security.js
 */

const app = require('./app');

// Test base URL
const BASE_URL = 'http://localhost:3000';

// Utility functions
const axios = require('axios');

async function testEndpoint(url, options = {}) {
  try {
    const response = await axios({
      url,
      method: options.method || 'GET',
      params: options.params || {},
      headers: options.headers || {},
