function assessTest(test) {
  const { result, expectedStatus, checkHeaders, expectedHeaders } = test;

  // Check status code
  if (expectedStatus && result.status !== expectedStatus) {
    console.error(`  Expected status ${expectedStatus}, got ${result.status}`);
    return false;
  }

  // Check for error codes in 4xx/5xx responses
  if (result.status >= 400 && !test.errorCode) {
