// Improved application with robust error handling and input validation
// Security-focused implementation

const express = require('express');
const app = express();
const bodyParser = require('body-parser');
const rateLimit = require('express-rate-limit');

// Parse JSON bodies (limited size for security)
app.use(bodyParser.json({
  limit: '100kb', // Prevent memory exhaustion attacks
  verify: (req, res, buf) => {
    // Check for potential buffer overflow attempts
    if (buf.length > 100000) {
      throw new Error('RequestBodyTooLarge');
    }
  }
}));

// Parse URL-encoded bodies
app.use(bodyParser.urlencoded({
  extended: true,
  limit: '100kb'
}));

// Security headers
app.use((req, res, next) => {
  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Enable XSS protection
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Content Security Policy
  res.setHeader('Content-Security-Policy', "default-src 'self'; script-src 'self'");

  // Add referrer policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Allow CORS only for specific origins (adjust for your needs)
  res.setHeader('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS || '*');

  next();
});

// Security middleware for input sanitization
function sanitizeInput(input) {
  if (typeof input !== 'string') {
    return input;
  }

  // Remove control characters and null bytes
  return input.replace(/[\x00-\x1f\x7f]/g, '');
}

// Validate email format
function isValidEmail(email) {
  // Basic email validation using regex
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

// Rate limiting configuration
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    code: 'RATE_LIMIT_EXCEEDED'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use('/api', apiLimiter);

// Health check endpoint with request validation
app.get('/health', (req, res, next) => {
  try {
    // Validate request parameters if any
    const allowedStatus = ['ok', 'warning', 'error'];
    const status = req.query.status?.toLowerCase();

    if (status && !allowedStatus.includes(status)) {
      return res.status(400).json({
        error: 'Invalid status parameter',
        message: 'Status must be one of: ' + allowedStatus.join(', ')
      });
    }

    // Input sanitization
    const sanitizedStatus = sanitizeInput(status || 'ok');

    res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
    res.json({
      status: sanitizedStatus,
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with validation
app.get('/users', (req, res, next) => {
  try {
    // Validate and sanitize query parameters
    const limit = sanitizeInput(req.query.limit);
    const offset = sanitizeInput(req.query.offset);

    // Validate offset and limit
    const parsedLimit = limit ? parseInt(limit, 10) : null;
    const parsedOffset = offset ? parseInt(offset, 10) : null;

    if (parsedLimit !== null && (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100)) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        message: 'Limit must be a number between 1 and 100'
      });
    }

    if (parsedOffset !== null && (isNaN(parsedOffset) || parsedOffset < 0)) {
      return res.status(400).json({
        error: 'Invalid offset parameter',
        message: 'Offset must be a non-negative number'
      });
    }

    // Simulate pagination
    const actualLimit = Math.min(parsedLimit || 10, 100);
    const actualOffset = parsedOffset || 0;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' }
    ];

    const paginatedUsers = users.slice(actualOffset, actualOffset + actualLimit);

    res.json({
      data: paginatedUsers,
      meta: {
        limit: actualLimit,
        offset: actualOffset,
        total: users.length
      }
    });
  } catch (error) {
    next(error);
  }
});

// Example POST endpoint with full validation
app.post('/api/users', (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Validate required fields
    if (!name) {
      return res.status(400).json({
        error: 'Missing required field',
        message: 'Name is required'
      });
    }

    if (!email) {
      return res.status(400).json({
        error: 'Missing required field',
        message: 'Email is required'
      });
    }

    // Validate email format
    if (!isValidEmail(email)) {
      return res.status(400).json({
        error: 'Invalid email format',
        message: 'Please provide a valid email address'
      });
    }

    // Sanitize inputs
    const sanitized = {
      name: sanitizeInput(name),
      email: sanitizeInput(email)
    };

    // Add input length validation
    if (sanitized.name.length < 2 || sanitized.name.length > 100) {
      return res.status(400).json({
        error: 'Invalid name length',
        message: 'Name must be between 2 and 100 characters'
      });
    }

    if (sanitized.email.length > 255) {
      return res.status(400).json({
        error: 'Email length exceeded',
        message: 'Email cannot exceed 255 characters'
      });
    }

    // Check for common injection patterns
    const injectionPatterns = [
      /<script/i,
      /javascript:/i,
      /on\s*(error|load|click|mouseover)/i,
      /eval\(/i,
      /document\..*\.write/i
    ];

    for (const pattern of injectionPatterns) {
      if (pattern.test(sanitized.name) || pattern.test(sanitized.email)) {
        return res.status(400).json({
          error: 'Invalid input',
          message: 'Input contains potentially dangerous content'
        });
      }
    }

    // Process the input (example)
    // In real implementation, this would save to database
    const user = {
      id: Math.floor(Math.random() * 10000),
      name: sanitized.name,
      email: sanitized.email
    };

    res.status(201).json({
      data: user,
      message: 'User created successfully'
    });

  } catch (error) {
    next(error);
  }
});

// Global error handling middleware
// Must be placed after all route handlers
app.use((err, req, res, next) => {
  // Log the error for debugging (remove sensitive info in production)
  console.error('Error:', {
    name: err.name,
    message: err.message,
    path: req.path,
    method: req.method,
    body: JSON.stringify(req.body),
    query: JSON.stringify(req.query),
    ip: req.ip,
    userAgent: req.get('user-agent')
  });

  // Determine error type and response
  const statusCode = err.statusCode || 500;
  const errorResponse = {
    error: err.message || 'Internal Server Error',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  };

  // Prevent information leakage
  if (err.name === 'RequestBodyTooLarge') {
    return res.status(413).json({
      error: 'Payload Too Large',
      message: 'The request body exceeds the maximum allowed size'
    });
  }

  res.status(statusCode).json(errorResponse);
});

// Handle 404 errors
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Graceful shutdown handler
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  // Close server
  app.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

// Handle process termination
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Start server with proper error handling
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

