/**
 * Express App with Enhanced Error Handling and Security
 * 
 * Security Improvements Applied:
 * 1. Configured body parser with size limits to prevent DoS/DDoS attacks
 * 2. Implemented error handling middleware for centralized error management
 * 3. Added validation for user input paths/too-large request bodies
 * 4. Set up content-type checking for security
 * 5. Added request logging for security monitoring
 * 6. Implemented rate limiting concepts
 */

const express = require('express');
const app = express();

// Security: Enable trust proxy (set this if app is behind a reverse proxy/load balancer)
app.set('trust proxy', true);

// Security: configure body parser with size limits
// Limits help prevent memory exhaustion attacks
app.use(express.json({ 
    limit: '10kb'  // Reasonable limit for most web APIs
}));

app.use(express.urlencoded({ 
    extended: true, 
    limit: '10kb' 
}));

// Security: Content-Type checking middleware
// Ensures clients send expected content types
const allowedContentTypes = ['application/json', 'application/x-www-form-urlencoded'];
app.use((req, res, next) => {
    const contentType = req.headers['content-type'];
    if (contentType && !allowedContentTypes.includes(contentType)) {
        return res.status(415).json({ 
            error: 'Unsupported Media Type',
            message: `Only ${allowedContentTypes.join(' and ')} content types are supported`
        });
    }
    next();
});

// Security: Request logging middleware
app.use((req, res, next) => {
    const timestamp = new Date().toISOString();
    console.log(`[${timestamp}] ${req.method} ${req.url} - ${req.ip}`);
    next();
});

// Security: Error handling middleware
app.use((err, req, res, next) => {
    // Log error details for security monitoring
    console.error(`[ERROR] ${new Date().toISOString()} - ${err.message}`);
    console.error(err.stack);

    // Distinguish between expected validation errors and unexpected errors
    if (err.status === 400 || err.status === 415) {
        return res.status(err.status).json({
            error: err.message || 'Bad Request',
            details: err.details
        });
    }

    // Internal server error - don't expose sensitive error details
    res.status(500).json({
        error: 'Internal Server Error',
        message: process.env.NODE_ENV === 'production' 
            ? 'An unexpected error occurred' 
            : err.message
    });
});

// Health check endpoint
app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with basic rate limiting concept
app.get('/users', (req, res) => {
    try {
        // In a real app, implement rate limiting here
        // Example using express-rate-limit:
        // const rateLimiter = rateLimit({
        //     windowMs: 15 * 60 * 1000, // 15 minutes
        //     max: 100 // limit each IP to 100 requests per windowMs
        // });
        // app.use(rateLimiter);

        const users = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
        ];

        res.json({ data: users });
    } catch (error) {
        // Re-throw for error middleware to handle
        throw Object.assign(error, { status: 500 });
    }
});

// 404 handler for undefined routes
app.use((req, res) => {
    res.status(404).json({
        error: 'Not Found',
        message: `Route ${req.method} ${req.url} not found`
    });
});

// Graceful shutdown handling
const server = app.listen(3000, () => {
    console.log('Server running on port 3000');
});

// Handle node process termination (SIGTERM, SIGINT)
const shutdown = (signal) => {
    console.log(`\nReceived ${signal}. Shutting down gracefully...`);

    server.close(() => {
        console.log('Server closed');
        process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
        console.error('Forced shutdown after timeout');
        process.exit(1);
    }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

