// Secure application with proper error handling and input validation
// This demonstrates security best practices

const express = require('express');
const { body, validationResult } = require('express-validator');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');

const app = express();

// ===== SECURITY MIDDLEWARE =====

// Helmet: Sets various HTTP headers to help protect against common web vulnerabilities
app.use(helmet());

// Body parser limits to prevent DoS
app.use(express.json({ limit: '10kb' })); // JSON body size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // URL-encoded body size limit

// Data sanitization against NoSQL injection and XSS
app.use(xss()); // Sanitize HTML
app.use(mongoSanitize()); // Prevent NoSQL injection

// Request sanitization
app.use((req, res, next) => {
  // Strip potentially dangerous fields from query params
  Object.keys(req.query).forEach(key => {
    if (/^\.\.?\/|\.\./.test(req.query[key])) {
      delete req.query[key];
    }
  });
  next();
});

// Rate limiting: Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all routes
app.use(limiter);

// ===== VALIDATION MIDDLEWARE =====

// Validate result handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    const errorMessages = errors.array().map(error => ({
      param: error.param,
      msg: error.msg
    }));

    // Custom error response (HATEOAS-friendly)
    return res.status(400).json({
      success: false,
      status: 'error',
      message: 'Validation failed',
      errors: errorMessages
    });
  }
  next();
};

// ===== ROUTES =====

// Health endpoint with validation
app.get('/health', [
  // Validate query parameters (even though they're optional)
  query('timeout').optional().isInt({ min: 0, max: 60 }),
  handleValidationErrors
], (req, res) => {
  try {
    const { timeout } = req.query;
    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    if (timeout) {
      response.timeout = parseInt(timeout, 10);
    }

    res.json(response);
  } catch (error) {
    // Fallback error handling for unexpected errors
    console.error('Health check error:', error);
    res.status(500).json({
      success: false,
      status: 'error',
      message: 'Internal server error'
    });
  }
});

// Users endpoint with validation
app.get('/users', handleValidationErrors, (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { page = 1, limit = 10 } = req.query;

    // Validate pagination params (must be integers)
    const parsedPage = Math.max(1, parseInt(page, 10) || 1);
    const parsedLimit = Math.min(100, Math.max(1, parseInt(limit, 10) || 10));

    // In production, this would query a database with parameters
    // simulated users data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    res.json({
      success: true,
      data: users,
      pagination: {
        page: parsedPage,
        limit: parsedLimit,
        total: users.length
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      success: false,
      status: 'error',
      message: 'Internal server error'
    });
  }
});

// Future: POST endpoint example with validation
/*
app.post('/users', [
  body('name').trim().escape().isLength({ min: 1, max: 100 }),
  body('email').isEmail().normalizeEmail(),
  handleValidationErrors
], (req, res) => {
  // User creation logic here
});
*/

// ===== GLOBAL ERROR HANDLING =====

// Handle unexpected errors
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Differentiate between known and unknown errors
  const isKnown = err.statusCode && err.status;

  res.status(isKnown ? err.statusCode : 500).json({
    success: false,
    status: err.status || 'error',
    message: isKnown ? err.message : 'Internal server error'
  });
});

// Handle 404 Not Found
app.use((req, res) => {
  res.status(404).json({
    success: false,
    status: 'not_found',
    message: 'Route not found'
  });
});

// ===== SERVER CONFIGURATION =====

const PORT = process.env.PORT || 3000;

if (require.main === module) {
  // Graceful shutdown
  const server = app.listen(PORT, '0.0.0.0', () => {
    console.log(`Secure server running on port ${PORT}`);
    console.log(`Security features enabled: Helmet, XSS protection, NoSQL injection protection, Rate limiting`);
  });

  // Handle graceful shutdown
  process.on('SIGTERM', () => {
    console.log('SIGTERM signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    console.log('SIGINT signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });
}

module.exports = app;

#!/usr/bin/env node

/**
 * Security Test Suite
 * Tests various security features of the secure-express-app
 */

const http = require('http');

const BASE_URL = 'http://localhost:3000';
const PORT = 3000;
let requestCount = 0;

console.log('='.repeat(60));
console.log('SECURITY TEST SUITE FOR SECURE-EXPRESS-APP');
console.log('='.repeat(60));

// Helper function to make requests
function makeRequest(method, path, data = {}) {
  return new Promise((resolve, reject) => {
    const body = data ? JSON.stringify(data) : undefined;
    const options = {
      hostname: 'localhost',
      port: PORT,
      path,
      method,
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': body ? Buffer.byteLength(body) : 0,
        'User-Agent': 'SecurityTestBot/1.0'
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';
      res.on('data', chunk => responseData += chunk);
      res.on('end', () => {
        const response = {
          statusCode: res.statusCode,
          headers: res.headers,
          body: tryParseJSON(responseData) || responseData
        };
        requestCount++;
        resolve(response);
      });
    });

    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

function tryParseJSON(str) {
  try { return JSON.parse(str); } catch { return null; }
}

// Test functions
async function testHealthEndpoint() {
  console.log('\n[TEST 1] Health Endpoint');
  const response = await makeRequest('GET', '/health');
  console.log(`  Status: ${response.statusCode} ${response.statusCode === 200 ? '✅ PASS' : '❌ FAIL'}`);
  console.log(`  Response:`, response.body);
}

async function testValidationErrors() {
  console.log('\n[TEST 2] Validation Errors (Invalid Query Params)');
  const response = await makeRequest('GET', '/health?timeout=invalid');
  console.log(`  Status: ${response.statusCode} ${response.statusCode === 400 ? '✅ PASS' : '❌ FAIL'}`);
  console.log(`  Error Message:`, tryParseJSON(response.body)?.errors);
}

async function testPaginationValidation() {
  console.log('\n[TEST 3] Pagination Validation');
  // Test negative page number (should be normalized to 1)
  const response = await makeRequest('GET', '/users?page=-50&limit=5');
  console.log(`  Negative page test -> Status: ${response.statusCode}`);

  // Test large limit (should be capped at 100)
  const response2 = await makeRequest('GET', '/users?limit=200');
  console.log(`  Large limit test -> Status: ${response2.statusCode}`);

  // Test negative limit
  const response3 = await makeRequest('GET', '/users?limit=-10');
  console.log(`  Negative limit test -> Status: ${response3.statusCode}`);

  // Valid parameters
  const response4 = await makeRequest('GET', '/users?page=1&limit=5');
  console.log(`  Valid pagination -> Status: ${response4.statusCode}`);

  const allValid = response?.statusCode === 200;
  console.log(`  Overall Result: ${allValid ? '✅ PASS' : '❌ FAIL'}`);
}

async function testUrlSanitization() {
  console.log('\n[TEST 4] URL Parameter Sanitization');
  const response = await makeRequest('GET', '/users?..path=../../etc/passwd');
  const body = tryParseJSON(response.body);
  console.log(`  Payload: ../..path=../../etc/passwd`);
  console.log(`  Status: ${response.statusCode} ${body?.status === 'error' ? '✅ PASS' : '❌ FAIL'}`);
  console.log(`  Filtered sensitive params: ${body?.data ? 'Yes' : 'Unknown'}`);

  // Test malicious characters in query
  const response2 = await makeRequest('GET', '/users?name=<script>alert(1)</script>');
  console.log(`\n  XSS test: <script>alert(1)</script>`);
  console.log(`  Status: ${response2.statusCode} ${response2.body.includes('script') ? '❌ FAIL' : '✅ PASS'} (XSS should be sanitized)`);
}

async function testStatusCodes() {
  console.log('\n[TEST 5] Error Status Codes');

  // 404 Not Found
  const response = await makeRequest('GET', '/nonexistent');
  const has404Msg = tryParseJSON(response.body)?.message?.includes('not found');
  console.log(`  404 Status Code: ${response.statusCode} ${response.statusCode === 404 ? '✅ PASS' : '❌ FAIL'} (${has404Msg ? 'With message' : 'No message'})`);

  // Check rate limit headers
  const rateLimitMax = response.headers['x-ratelimit-max'];
  console.log(`  Rate Limit Headers Present: ${!!rateLimitMax ? '✅ PASS' : '⚠️  CHECK'} (Max: ${rateLimitMax || 'Not present'})`);
}

async function testPerformance() {
  console.log('\n[TEST 6] Performance (Sequential Requests)');

  const startTime = Date.now();
  const healthResponse = await makeRequest('GET', '/health');
  const usersResponse = await makeRequest('GET', '/users?page=2&limit=20');

  const duration = Date.now() - startTime;
  console.log(`  2 requests completed in ${duration}ms`);

  if (healthResponse.statusCode === 200 && usersResponse.statusCode === 200) {
    console.log(`  Response Integrity: ✅ PASS`);
    console.log(`  Average time per request: ${Math.round(duration / 2)}ms`);
  }
}

async function runAllTests() {
  await testHealthEndpoint();
  await testValidationErrors();
  await testPaginationValidation();
  await testUrlSanitization();
  await testStatusCodes();
  await testPerformance();

  console.log('\n' + '='.repeat(60));
  console.log('SECURITY TEST SUITE COMPLETE');
  console.log(`  Total requests made: ${requestCount}`);
  console.log('='.repeat(60));

  console.log('\n⚠️  Note: Rate limiting will affect subsequent tests if run multiple times');
  console.log('   Run "npm start" first, then run "node test-security.js"');
}

// Check if server is running
async function checkServer() {
  try {
    await makeRequest('GET', '/health');
    return true;
  } catch {
    return false;
  }
}

(async () => {
  const serverRunning = await checkServer();

  if (serverRunning) {
    await runAllTests();
  } else {
    console.log('\n❌ Server is not running!\n');
    console.log('To run the tests:');
    console.log('  1. Install dependencies: npm install');
    console.log('  2. Start server: npm start');
    console.log('  3. Run tests: node test-security.js\n');
  }
})();

