const sanitizeResponse = (obj) => {
  if (!obj || typeof obj !== 'object') return obj;

  // List of fields to exclude from all responses
  const sensitiveFields = [
    'password',
    'password_hash',
    'token',
    'refresh_token',
    'secret',
    'apiKey',
    'privateKey'
